Поширений формат співбесіди: тобі показують тест і питають **«що тут не так?»**. Знайди якомога більше проблем і перепиши тест правильно.

```ts
import { test, expect } from '@playwright/test';

let orderId;

test('test1', async ({ page }) => {
  await page.goto('http://localhost:5173/playground/login');
  await page.fill('#root > div > div:nth-child(2) > form > input:nth-child(1)', 'qa@gadgetly.test');
  await page.fill('input[type=password]', 'Test1234');
  page.click('.btn-primary');
  await page.waitForTimeout(3000);
  const visible = await page.locator('text=Welcome').isVisible();
  expect(visible).toBe(true);
  orderId = await page.locator('.order-id').textContent();
});

test('test2', async ({ page }) => {
  await page.goto('http://localhost:5173/orders/' + orderId);
  await page.locator('.cancel').click({ force: true });
  expect(await page.locator('.status').textContent()).toBe('Cancelled');
});
```

